		if (extending == null) {
			annotationNode.addError("@StandardException requires that you extend a Throwable type");
			return;
		}

		AccessLevel access = annotation.getInstance().access();
		if (access == null) access = AccessLevel.PUBLIC;
		if (access == AccessLevel.NONE) {
			annotationNode.addError("AccessLevel.NONE is not valid here");
			access = AccessLevel.PUBLIC;
		}

		this.activeTypeNode = typeNode;
		this.activeSourceNode = annotationNode;
		this.activeAccessLevel = access;
		bindExceptionGenerationContext(typeNode, annotationNode, access, extending);
		prepareStandardExceptionPlan();
		if (shouldSkipBecauseAborted() && !isClass(typeNode)) {
